fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Requires: The length of `sub` must not exceed the remaining length of `main` from `start`.
    // Ensures: Returns true if the subarray matches the main array starting at index `start`, false otherwise.
    // Invariant: 0 <= start <= main.len() and sub.len() > 0 implies start + sub.len() <= main.len()
    // Decreases: main.len() - start

    assert!(start <= main.len()); // Ensure start is within bounds
    assert!(sub.len() <= main.len() - start); // Ensure sub can fit in main from start

    if start + sub.len() > main.len() {
        return false;
    }
    
    // Check if the elements match
    for j in 0..sub.len() {
        assert!(j < sub.len()); // Ensure j is within bounds of sub
        assert!(start + j < main.len()); // Ensure start + j is within bounds of main
        if main[start + j] != sub[j] {
            return false;
        }
    }
    
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // Requires: The length of `sub` must be non-negative.
    // Ensures: Returns true if `sub` is a subarray of `main`, false otherwise.
    // Invariant: For each k in 0..=main.len() - sub.len(), check_match_at(main, sub, k)
    // Decreases: main.len() - sub.len()

    assert!(sub.len() >= 0); // Ensure sub has non-negative length

    // An empty subarray is always a valid subarray
    if sub.is_empty() {
        return true;
    }
    
    // Check each possible starting index in the main array
    for k in 0..=main.len().saturating_sub(sub.len()) {
        assert!(k <= main.len() - sub.len()); // Ensure k is a valid starting index
        if check_match_at(main, sub, k) {
            return true;
        }
    }
    
    false
}

